// Cleanup worker. The old Chirpy theme installed a service worker at this
// URL that cached the whole site in visitors' browsers. This replacement
// clears that cache and removes itself, so returning visitors get the
// current site. Safe to delete this file a few months after the switch.
self.addEventListener('install', () => self.skipWaiting());

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));
      await self.registration.unregister();
      const windows = await self.clients.matchAll({ type: 'window' });
      windows.forEach((client) => client.navigate(client.url));
    })()
  );
});
